"""Snap span boundaries to a fixed step, for payroll."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span


def check_step(step: int) -> None:
    """Steps must be positive and divide an hour evenly."""
    if not isinstance(step, int) or step <= 0:
        raise ValueError(f"step must be positive: {step!r}")
    if 60 % step:
        raise ValueError(f"step must fit an hour: {step}")


def round_minute(value: int, step: int) -> int:
    """Nearest multiple of step. Halfway rounds up."""
    return (value + step // 2) // step * step


def round_span(span: Span, step: int) -> Span:
    """Both ends snapped. ValueError if it collapses."""
    check_step(step)
    start = round_minute(span.start, step)
    return Span(start, round_minute(span.end, step))


def format_duration(minutes: int) -> str:
    hours, remainder = divmod(minutes, 60)
    return f"{hours}h {remainder}m"


def span_label(span: Span) -> str:
    """Text such as 09:00-17:15 (8h 15m)."""
    length = format_duration(span.minutes)
    return f"{format_span(span)} ({length})"


def rounded_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """One label per span, in order, after rounding."""
    check_step(step)
    rounded = [round_span(item, step) for item in spans]
    return [span_label(item) for item in rounded]

