import unittest

from hourglass.models import Span
from hourglass.rounding import (
    round_minute,
    round_span,
    rounded_labels,
    span_label
)


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels([Span(540, 600)], step)

    def test_good_steps_accepted(self):
        for step in (1, 5, 6, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                result = rounded_labels([], step)
                self.assertEqual(result, [])


class RoundingTests(unittest.TestCase):
    def test_nearest(self):
        self.assertEqual(round_minute(542, 15), 540)
        self.assertEqual(round_minute(548, 15), 555)

    def test_halfway_rounds_up(self):
        self.assertEqual(round_minute(35, 10), 40)
        self.assertEqual(round_minute(30, 60), 60)

    def test_span_both_ends(self):
        result = round_span(Span(542, 1018), 15)
        self.assertEqual(result, Span(540, 1020))

    def test_end_of_day(self):
        result = round_span(Span(1400, 1439), 30)
        self.assertEqual(result, Span(1410, 1440))

    def test_collapsing_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 545), 15)


class LabelTests(unittest.TestCase):
    def test_label(self):
        self.assertEqual(
            span_label(Span(540, 1035)),
            "09:00-17:15 (8h 15m)"
        )

    def test_labels_after_rounding(self):
        spans = [Span(541, 1034), Span(1100, 1200)]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)", "18:15-20:00 (1h 45m)"]
        )

    def test_empty(self):
        self.assertEqual(rounded_labels([], 15), [])


if __name__ == "__main__":
    unittest.main()
